// Blender 5.2's AgX display transform, as data.
//
// AgX is not a curve — it is a 3x3 into FilmLight E-Gamut, a log2 encoding across
// 25 stops, a 57³ lookup, and a Rec.1886 decode on the way out. Blender ships the
// lookup itself as release/datafiles/colormanagement/luts/AgX_Base_sRGB.cube, so
// this is that file, not a reconstruction of it: packed rgb10a2unorm (10 bits is
// four past what an 8-bit display resolves, leaving headroom for the grade that
// runs after) and gzipped, which browsers decompress natively.
//
// 723 KB raw becomes 120 KB compressed. Resampling to a smaller grid was measured
// and rejected: the error concentrates at saturated mid-scene values — bright
// cyan and green, where AgX does its heaviest hue rotation — and stays above
// 27/255 even at 41³, because the LUT genuinely has high-frequency content there.
//
// Regenerate with tools/pack-agx.mjs when Blender's LUT changes.
export const AGX_LUT_SIZE = 57
/** Scene-linear Rec.709 → FilmLight E-Gamut. Derived from config.ocio: the
 *  scene_linear role IS Linear Rec.709, so the ACES reference hop cancels and
 *  only Rec.709→XYZ-D65 and the config's stated XYZ→E-Gamut matrix survive.
 *  Verified: (1,1,1) maps to (1,1,1), both being D65. */
export const AGX_INSET = [
  0.55937113, 0.30478326, 0.13584556,
  0.07622071, 0.78797183, 0.13580748,
  0.06552670, 0.16454675, 0.76992653,
] as const
/** OCIO lg2 allocation the cube expects: log2(x) mapped from these stops to 0..1. */
export const AGX_MIN_EV = -12.47393
export const AGX_MAX_EV = 12.5260688117
export const AGX_LUT_GZ =
  ""
